CREATE TRIGGER RefCusVATApplicability_Combined
	ON RefCusVATApplicability
	FOR INSERT, UPDATE, DELETE
	AS
	IF (SELECT CASE WHEN EXISTS(SELECT 1 FROM INSERTED) AND NOT EXISTS(SELECT 1 FROM DELETED) THEN 1 ELSE 0 end) = 1
	BEGIN
		UPDATE t SET
		ZX5_DataSetPK = COALESCE(inserted.ZX5_ZZ1_Tariff, ZZW_ZZ1_Tariff),
		ZX5_DataSetCode = CASE WHEN inserted.ZX5_ZZ1_Tariff IS NOT NULL THEN 'ZZ1' ELSE CASE WHEN ZZW_ZZ1_Tariff IS NOT NULL THEN 'ZZ1' END END 
		FROM RefCusVATApplicability t
		JOIN inserted ON t.ZX5_PK = inserted.ZX5_PK
		LEFT JOIN RefCusTariffNationalCode ON inserted.ZX5_ZZW_TariffNationalCode = ZZW_PK
	END

	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT t.ZX5_DataSetPK, t.ZX5_DataSetCode
	FROM RefCusVATApplicability t
	JOIN inserted ON t.ZX5_PK = inserted.ZX5_PK
	UNION
	SELECT ZX5_DataSetPK, ZX5_DataSetCode
	FROM deleted

	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN @sourcePK ON RVC_ParentPK = PK AND RVC_ParentCode = TablePrefix
	WHERE RVC_IsPublished = 1

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO

CREATE TRIGGER RefCusVATApplicability_DataProcessingResult_Delete
	ON RefCusVATApplicability
	FOR DELETE
	AS
	BEGIN
		DELETE dpr
		FROM dbo.RefStagingDatabase_DataProcessingResult dpr
		JOIN deleted d ON dpr.DPR_ParentPK = d.ZX5_PK
	END
GO
